'use strict';

const fs = require('node:fs');
const path = require('node:path');

const FILE_NAME = 'todos.json';

const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo
  list             List all todos
  complete <id>    Mark a todo as done
  delete <id>      Delete a todo
  help             Show this help message`;

// Errors caused by user input or bad data; reported without a stack trace.
class TodoError extends Error {}

function emptyStore() {
  return { nextId: 1, todos: [] };
}

// Reads the store from disk. A missing or blank file is an empty list. A bare
// array of todos is also accepted so a hand-written file still works.
function load(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return emptyStore();
    throw err;
  }
  if (raw.trim() === '') return emptyStore();

  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new TodoError(`${path.basename(file)} is not valid JSON. Fix or remove it and try again.`);
  }

  const todos = Array.isArray(data) ? data : data?.todos;
  if (!Array.isArray(todos) || !todos.every(isTodo)) {
    throw new TodoError(`${path.basename(file)} has an unexpected format. Fix or remove it and try again.`);
  }

  // nextId keeps ids from being reused after a delete; never let it fall
  // behind the ids already in the file.
  const maxId = todos.reduce((max, todo) => Math.max(max, todo.id), 0);
  const storedNextId = Number.isSafeInteger(data.nextId) ? data.nextId : 1;
  return { nextId: Math.max(storedNextId, maxId + 1), todos };
}

function isTodo(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    Number.isSafeInteger(value.id) &&
    value.id > 0 &&
    typeof value.text === 'string' &&
    typeof value.completed === 'boolean'
  );
}

// Writes via a temp file + rename so an interrupted write can't leave a
// truncated todos.json behind.
function save(file, store) {
  const tmp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n');
  fs.renameSync(tmp, file);
}

function parseId(raw, command) {
  if (raw === undefined) {
    throw new TodoError(`A todo id is required. Usage: node index.js ${command} <id>`);
  }
  const id = Number(raw);
  if (!/^\d+$/.test(raw) || !Number.isSafeInteger(id) || id < 1) {
    throw new TodoError(`Invalid id "${raw}". The id must be a positive integer.`);
  }
  return id;
}

function findTodo(store, id) {
  const todo = store.todos.find((t) => t.id === id);
  if (!todo) throw new TodoError(`No todo found with id ${id}.`);
  return todo;
}

function addTodo(store, text, now = new Date()) {
  const todo = {
    id: store.nextId,
    text,
    completed: false,
    createdAt: now.toISOString(),
  };
  store.todos.push(todo);
  store.nextId += 1;
  return todo;
}

// Returns true if the todo changed, false if it was already completed.
function completeTodo(store, id) {
  const todo = findTodo(store, id);
  if (todo.completed) return false;
  todo.completed = true;
  return true;
}

function deleteTodo(store, id) {
  const todo = findTodo(store, id);
  store.todos = store.todos.filter((t) => t !== todo);
  return todo;
}

function formatList(todos) {
  if (todos.length === 0) {
    return 'No todos yet. Add one with: node index.js add "<text>"';
  }
  return [...todos]
    .sort((a, b) => a.id - b.id)
    .map((t) => `${t.id}. [${t.completed ? 'x' : ' '}] ${t.text}`)
    .join('\n');
}

// Runs a CLI command and returns the process exit code.
function run(args, { cwd = process.cwd(), stdout = process.stdout, stderr = process.stderr } = {}) {
  const file = path.join(cwd, FILE_NAME);
  const [command, ...rest] = args;
  const print = (msg) => stdout.write(msg + '\n');

  const requireSingleId = () => {
    if (rest.length > 1) {
      throw new TodoError(`Too many arguments. Usage: node index.js ${command} <id>`);
    }
    return parseId(rest[0], command);
  };

  try {
    switch (command) {
      case 'add': {
        // Join so unquoted input (`add Buy milk`) works too.
        const text = rest.join(' ').trim();
        if (text === '') {
          throw new TodoError('Todo text is required. Usage: node index.js add "<text>"');
        }
        const store = load(file);
        const todo = addTodo(store, text);
        save(file, store);
        print(`Added todo ${todo.id}: ${todo.text}`);
        return 0;
      }

      case 'list': {
        print(formatList(load(file).todos));
        return 0;
      }

      case 'complete': {
        const id = requireSingleId();
        const store = load(file);
        if (!completeTodo(store, id)) {
          print(`Todo ${id} is already completed.`);
          return 0;
        }
        save(file, store);
        print(`Completed todo ${id}: ${findTodo(store, id).text}`);
        return 0;
      }

      case 'delete': {
        const id = requireSingleId();
        const store = load(file);
        const todo = deleteTodo(store, id);
        save(file, store);
        print(`Deleted todo ${id}: ${todo.text}`);
        return 0;
      }

      case 'help':
      case '--help':
      case '-h':
        print(USAGE);
        return 0;

      case undefined:
        stderr.write(USAGE + '\n');
        return 1;

      default:
        stderr.write(`Error: Unknown command "${command}".\n\n${USAGE}\n`);
        return 1;
    }
  } catch (err) {
    if (!(err instanceof TodoError)) throw err;
    stderr.write(`Error: ${err.message}\n`);
    return 1;
  }
}

module.exports = {
  FILE_NAME,
  USAGE,
  TodoError,
  load,
  save,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
  run,
};

