'use strict';

const { describe, test, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const todo = require('../lib/todo');

describe('parseId', () => {
  test('parses positive integers', () => {
    assert.equal(todo.parseId('1', 'complete'), 1);
    assert.equal(todo.parseId('42', 'complete'), 42);
  });

  test('throws when the id is missing', () => {
    assert.throws(() => todo.parseId(undefined, 'delete'), {
      name: 'Error',
      message: /id is required.*delete <id>/,
    });
  });

  for (const bad of ['0', '-1', '1.5', 'abc', '1abc', '', ' 1', '1e3', '0x10', '99999999999999999999']) {
    test(`rejects ${JSON.stringify(bad)}`, () => {
      assert.throws(() => todo.parseId(bad, 'complete'), todo.TodoError);
    });
  }
});

describe('store operations', () => {
  let store;
  beforeEach(() => {
    store = { nextId: 1, todos: [] };
  });

  test('addTodo creates a todo with all required fields', () => {
    const now = new Date('2026-01-02T03:04:05.678Z');
    const added = todo.addTodo(store, 'Buy groceries', now);
    assert.deepEqual(added, {
      id: 1,
      text: 'Buy groceries',
      completed: false,
      createdAt: '2026-01-02T03:04:05.678Z',
    });
    assert.deepEqual(store.todos, [added]);
    assert.equal(store.nextId, 2);
  });

  test('addTodo auto-increments ids', () => {
    const ids = ['a', 'b', 'c'].map((t) => todo.addTodo(store, t).id);
    assert.deepEqual(ids, [1, 2, 3]);
  });

  test('completeTodo marks a todo done and reports whether it changed', () => {
    todo.addTodo(store, 'a');
    assert.equal(todo.completeTodo(store, 1), true);
    assert.equal(store.todos[0].completed, true);
    assert.equal(todo.completeTodo(store, 1), false);
    assert.equal(store.todos[0].completed, true);
  });

  test('completeTodo throws for an unknown id', () => {
    assert.throws(() => todo.completeTodo(store, 7), {
      message: 'No todo found with id 7.',
    });
  });

  test('deleteTodo removes only the matching todo', () => {
    todo.addTodo(store, 'a');
    todo.addTodo(store, 'b');
    todo.addTodo(store, 'c');
    const removed = todo.deleteTodo(store, 2);
    assert.equal(removed.text, 'b');
    assert.deepEqual(store.todos.map((t) => t.id), [1, 3]);
  });

  test('deleteTodo throws for an unknown id', () => {
    assert.throws(() => todo.deleteTodo(store, 1), todo.TodoError);
  });

  test('ids are not reused after deleting the newest todo', () => {
    todo.addTodo(store, 'a');
    todo.addTodo(store, 'b');
    todo.deleteTodo(store, 2);
    assert.equal(todo.addTodo(store, 'c').id, 3);
  });
});

describe('formatList', () => {
  test('shows a friendly message when empty', () => {
    assert.match(todo.formatList([]), /No todos yet/);
  });

  test('shows id, status indicator and text, sorted by id', () => {
    const output = todo.formatList([
      { id: 3, text: 'Third', completed: false },
      { id: 1, text: 'First', completed: true },
      { id: 2, text: 'Second', completed: false },
    ]);
    assert.equal(output, '1. [x] First\n2. [ ] Second\n3. [ ] Third');
  });
});

