'use strict';

const { describe, test, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const INDEX = path.join(__dirname, '..', 'index.js');

let dir;
let file;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
  file = path.join(dir, 'todos.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

// Runs the real CLI with the temp dir as the current directory.
function cli(...args) {
  const result = spawnSync(process.execPath, [INDEX, ...args], { cwd: dir, encoding: 'utf8' });
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

function readStore() {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function assertOk(result) {
  assert.equal(result.code, 0, `expected success, stderr: ${result.stderr}`);
  assert.equal(result.stderr, '');
}

function assertFails(result, pattern) {
  assert.equal(result.code, 1, `expected failure, stdout: ${result.stdout}`);
  assert.match(result.stderr, pattern);
  assert.equal(result.stdout, '');
}

describe('general usage', () => {
  test('no command prints usage and exits 1', () => {
    const result = cli();
    assert.equal(result.code, 1);
    assert.match(result.stderr, /Usage: node index\.js <command>/);
  });

  for (const flag of ['help', '--help', '-h']) {
    test(`"${flag}" prints usage and exits 0`, () => {
      const result = cli(flag);
      assertOk(result);
      assert.match(result.stdout, /Usage:/);
      for (const cmd of ['add', 'list', 'complete', 'delete']) {
        assert.match(result.stdout, new RegExp(`\\b${cmd}\\b`));
      }
    });
  }

  test('an unknown command is an error', () => {
    const result = cli('frobnicate');
    assertFails(result, /Unknown command "frobnicate"/);
    assert.match(result.stderr, /Usage:/);
  });

  test('commands are case-sensitive', () => {
    assertFails(cli('ADD', 'x'), /Unknown command "ADD"/);
  });

  test('read-only commands do not create todos.json', () => {
    cli('list');
    cli('help');
    cli();
    assert.equal(fs.existsSync(file), false);
  });
});

describe('add', () => {
  test('adds a todo with id, text, completed and createdAt', () => {
    const before = Date.now();
    const result = cli('add', 'Buy groceries');
    const after = Date.now();

    assertOk(result);
    assert.equal(result.stdout, 'Added todo 1: Buy groceries\n');

    const [todo, ...rest] = readStore().todos;
    assert.equal(rest.length, 0);
    assert.deepEqual(Object.keys(todo).sort(), ['completed', 'createdAt', 'id', 'text']);
    assert.equal(todo.id, 1);
    assert.equal(todo.text, 'Buy groceries');
    assert.equal(todo.completed, false);
    assert.equal(new Date(todo.createdAt).toISOString(), todo.createdAt);
    const created = Date.parse(todo.createdAt);
    assert.ok(created >= before && created <= after, 'createdAt should be the current time');
  });

  test('auto-increments ids', () => {
    cli('add', 'One');
    cli('add', 'Two');
    const result = cli('add', 'Three');
    assert.equal(result.stdout, 'Added todo 3: Three\n');
    assert.deepEqual(readStore().todos.map((t) => t.id), [1, 2, 3]);
  });

  test('does not reuse the id of a deleted todo', () => {
    cli('add', 'One');
    cli('add', 'Two');
    cli('delete', '2');
    cli('add', 'Three');
    assert.deepEqual(readStore().todos.map((t) => t.id), [1, 3]);
  });

  test('joins unquoted words into one todo', () => {
    cli('add', 'Buy', 'more', 'milk');
    assert.equal(readStore().todos[0].text, 'Buy more milk');
  });

  test('trims surrounding whitespace', () => {
    cli('add', '   Walk the dog  ');
    assert.equal(readStore().todos[0].text, 'Walk the dog');
  });

  test('preserves quotes, symbols and unicode', () => {
    const text = `Say "hi" & it's 100% done — café ✅`;
    cli('add', text);
    assert.equal(readStore().todos[0].text, text);
    assert.match(cli('list').stdout, new RegExp(`\\[ \\] ${text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`));
  });

  test('missing text is an error and creates no file', () => {
    assertFails(cli('add'), /Todo text is required/);
    assert.equal(fs.existsSync(file), false);
  });

  test('empty or whitespace-only text is an error', () => {
    assertFails(cli('add', ''), /Todo text is required/);
    assertFails(cli('add', '   '), /Todo text is required/);
    assert.equal(fs.existsSync(file), false);
  });
});

describe('list', () => {
  test('shows a friendly message when there is no todos.json', () => {
    const result = cli('list');
    assertOk(result);
    assert.match(result.stdout, /No todos yet/);
  });

  test('shows a friendly message after every todo is deleted', () => {
    cli('add', 'Temporary');
    cli('delete', '1');
    assert.match(cli('list').stdout, /No todos yet/);
  });

  test('shows id, status indicator and text for each todo', () => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('add', 'Write report');
    cli('complete', '2');

    const result = cli('list');
    assertOk(result);
    assert.equal(
      result.stdout,
      ['1. [ ] Buy groceries', '2. [x] Walk the dog', '3. [ ] Write report', ''].join('\n'),
    );
  });

  test('ignores extra arguments', () => {
    cli('add', 'Only');
    const result = cli('list', 'extra');
    assertOk(result);
    assert.equal(result.stdout, '1. [ ] Only\n');
  });
});

describe('complete', () => {
  beforeEach(() => {
    cli('add', 'First');
    cli('add', 'Second');
  });

  test('marks a todo as done and leaves others alone', () => {
    const result = cli('complete', '1');
    assertOk(result);
    assert.equal(result.stdout, 'Completed todo 1: First\n');

    const todos = readStore().todos;
    assert.equal(todos[0].completed, true);
    assert.equal(todos[1].completed, false);
  });

  test('keeps the other fields unchanged', () => {
    const before = readStore().todos[0];
    cli('complete', '1');
    assert.deepEqual(readStore().todos[0], { ...before, completed: true });
  });

  test('completing an already-completed todo is a no-op', () => {
    cli('complete', '2');
    const result = cli('complete', '2');
    assertOk(result);
    assert.match(result.stdout, /Todo 2 is already completed/);
    assert.equal(readStore().todos[1].completed, true);
  });

  test('missing id is an error', () => {
    assertFails(cli('complete'), /id is required.*complete <id>/);
  });

  for (const bad of ['abc', '0', '-1', '1.5', '2x']) {
    test(`invalid id "${bad}" is an error and changes nothing`, () => {
      const before = fs.readFileSync(file, 'utf8');
      assertFails(cli('complete', bad), new RegExp(`Invalid id "${bad.replace('.', '\\.')}"`));
      assert.equal(fs.readFileSync(file, 'utf8'), before);
    });
  }

  test('a nonexistent id is an error', () => {
    assertFails(cli('complete', '99'), /No todo found with id 99/);
    assert.ok(readStore().todos.every((t) => !t.completed));
  });

  test('a nonexistent id is an error when the list is empty', () => {
    fs.rmSync(file);
    assertFails(cli('complete', '1'), /No todo found with id 1/);
    assert.equal(fs.existsSync(file), false);
  });

  test('more than one id is an error', () => {
    assertFails(cli('complete', '1', '2'), /Too many arguments/);
    assert.ok(readStore().todos.every((t) => !t.completed));
  });
});

describe('delete', () => {
  beforeEach(() => {
    cli('add', 'First');
    cli('add', 'Second');
    cli('add', 'Third');
  });

  test('removes the todo and keeps the rest', () => {
    const result = cli('delete', '2');
    assertOk(result);
    assert.equal(result.stdout, 'Deleted todo 2: Second\n');
    assert.deepEqual(readStore().todos.map((t) => t.text), ['First', 'Third']);
    assert.equal(cli('list').stdout, '1. [ ] First\n3. [ ] Third\n');
  });

  test('can delete a completed todo', () => {
    cli('complete', '1');
    assertOk(cli('delete', '1'));
    assert.deepEqual(readStore().todos.map((t) => t.id), [2, 3]);
  });

  test('deleting the same id twice fails the second time', () => {
    assertOk(cli('delete', '1'));
    assertFails(cli('delete', '1'), /No todo found with id 1/);
    assert.equal(readStore().todos.length, 2);
  });

  test('missing id is an error', () => {
    assertFails(cli('delete'), /id is required.*delete <id>/);
    assert.equal(readStore().todos.length, 3);
  });

  for (const bad of ['abc', '0', '-3', '2.0']) {
    test(`invalid id "${bad}" is an error and changes nothing`, () => {
      const before = fs.readFileSync(file, 'utf8');
      assertFails(cli('delete', bad), /Invalid id/);
      assert.equal(fs.readFileSync(file, 'utf8'), before);
    });
  }

  test('a nonexistent id is an error', () => {
    assertFails(cli('delete', '42'), /No todo found with id 42/);
    assert.equal(readStore().todos.length, 3);
  });

  test('more than one id is an error', () => {
    assertFails(cli('delete', '1', '2'), /Too many arguments/);
    assert.equal(readStore().todos.length, 3);
  });
});

describe('storage', () => {
  test('todos.json is written to the current directory', () => {
